const input = $json;

const traceId = String(input.traceId ?? '').trim();
const channel = String(input.channel ?? '').trim();
const sender = String(input.sender ?? '').trim();
const message = String(input.message ?? '').trim();
const intent = String(input.intent ?? '').trim().toUpperCase();

let valid = true;
const errors = [];

if (!traceId) { valid = false; errors.push('Falta traceId'); }
if (!channel) { valid = false; errors.push('Falta channel'); }
if (!sender) { valid = false; errors.push('Falta sender'); }
if (!message) { valid = false; errors.push('Falta message'); }

if (intent !== 'FACTURA_PAGO') {
  valid = false;
  errors.push('Intent invalido para Worker Facturacion');
}

return {
  json: {
    traceId,
    timestamp: new Date().toISOString(),

    channel,
    sender,
    message,
    intent,

    validation: {
      valid,
      errors
    }
  }
};

const input = $json;

return {
  json: {
    status: 'RECHAZADO',
    approved: false,
    response: null,

    error: {
      code: 'INVALID_WORKER_INPUT',
      message: 'La entrada recibida por el Worker de Facturacion no cumple con los campos requeridos.',
      details: input.validation?.errors ?? []
    },

    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    worker: {
      workflow: 'WF_WORKER_FACTURACION',
      stage: 'VALIDACION_ENTRADA'
    }
  }
};

const response = $json;
const ranges = response.valueRanges || [];

const rowsToObjects = (values) => {
  if (!values || values.length < 2) return [];
  const headers = values[0].map(h => String(h).trim().toLowerCase());
  return values.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = row[i] ?? null;
    });
    return obj;
  });
};

const rowsToKeyValue = (values) => {
  if (!values || values.length < 2) return {};
  const map = {};
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    const k = String(row[0] || '').trim();
    const v = String(row[1] || '').trim();
    if (k) map[k] = v;
  }
  return map;
};

// Cambio: includes('INFO-PAGOS') en lugar de startsWith('INFO_PAGOS')
const infoPagosRange = ranges.find(r =>
  String(r.range || '').toUpperCase().includes('INFO-PAGOS')
);
const reservasRange = ranges.find(r =>
  String(r.range || '').toUpperCase().startsWith('RESERVAS')
);
const tarifasRange = ranges.find(r =>
  String(r.range || '').toUpperCase().startsWith('TARIFAS')
);

const infoPagos = rowsToKeyValue(infoPagosRange?.values || []);
const reservas = rowsToObjects(reservasRange?.values || []);
const tarifas = rowsToObjects(tarifasRange?.values || []);

return {
  json: {
    infoPagos: infoPagos,
    reservas: reservas,
    tarifas: tarifas,
    _meta: {
      infoPagosKeys: Object.keys(infoPagos).length,
      reservasRows: reservas.length,
      tarifasRows: tarifas.length
    }
  }
};

const sheets = $('04b - Parsear Sheets').first().json;
const ctx = $('02 - Validar Entrada').first().json;

const infoPagos = sheets.infoPagos || {};
const reservas = sheets.reservas || [];
const tarifas = sheets.tarifas || [];

// ---------- Utilidades ----------
const toISO = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  return null;
};

const diffDays = (a, b) => {
  const d1 = new Date(a + 'T00:00:00Z');
  const d2 = new Date(b + 'T00:00:00Z');
  return Math.max(1, Math.round((d2 - d1) / (24 * 60 * 60 * 1000)));
};

const categoriaDeHabitacion = (id) => {
  const prefijo = String(id).split('-')[0].toUpperCase();
  const mapa = { STD: 'STANDARD', SUP: 'SUPERIOR', PRE: 'PREMIUM' };
  return mapa[prefijo] || null;
};

// ---------- Detectar reserva_id en el mensaje ----------
const mensajeOriginal = ctx.message || '';
// Patrón: RES-<timestamp>-<random>
const matchReserva = mensajeOriginal.match(/RES-\d+-[a-z0-9]+/i);
const reservaIdSolicitada = matchReserva ? matchReserva[0] : null;

// ---------- Detectar reclamo de cobro ----------
const esReclamoCobro = /\b(cobr(o|aron|o otra vez|o dos veces|o mal)|doble cobro|me cobraron|error de cobro|reintegro|devoluci[oó]n)\b/i.test(mensajeOriginal);

// ---------- Buscar reserva si pidió por ID ----------
let reservaEncontrada = null;
let montoPendiente = null;
let nochesReserva = 0;

if (reservaIdSolicitada) {
  reservaEncontrada = reservas.find(r => 
    String(r.reserva_id || '').trim().toLowerCase() === reservaIdSolicitada.toLowerCase()
  ) || null;

  if (reservaEncontrada) {
    const rIni = toISO(reservaEncontrada.fecha_entrada);
    const rFin = toISO(reservaEncontrada.fecha_salida);

    if (rIni && rFin) {
      nochesReserva = rFin > rIni ? diffDays(rIni, rFin) : 1;
    }

    // Buscar tarifa de la categoría
    const cat = categoriaDeHabitacion(reservaEncontrada.habitacion_id);
    const tarifa = tarifas.find(t => 
      String(t.categoria || '').trim().toUpperCase() === cat
    );

    if (tarifa) {
      const precioBase = Number(tarifa.precio_base);
      // No sabemos ocupación real de la reserva (no está en RESERVAS), 
      // asumimos 1 persona para el cálculo mínimo
      const precioNoche = precioBase;
      montoPendiente = precioNoche * nochesReserva;
    }
  }
}

// ---------- Info de pago de la hoja ----------
// Exponemos solo lo que el LLM puede usar, sin exponer toda la hoja
const infoPagoPublica = {
  cbu: infoPagos['CBU'] || null,
  alias: infoPagos['Alias'] || null,
  titular: infoPagos['Titular'] || null,
  plazoPago: infoPagos['Plazo de pago'] || null,
  recargoTarjeta: infoPagos['Recargo tarjeta'] || null,
  descuentoTransferencia: infoPagos['Descuento transferencia'] || null,
  mediosAceptados: infoPagos['Medios aceptados'] || null,
  emailFacturacion: infoPagos['Email de facturación'] || null,
  telefonoCobranzas: infoPagos['Teléfono de cobranzas'] || null
};

// ---------- Output ----------
const json = {
  traceId: ctx.traceId,
  timestamp: ctx.timestamp,
  channel: ctx.channel,
  sender: ctx.sender,
  message: ctx.message,
  intent: ctx.intent,

  result: {
    infoPago: infoPagoPublica,

    reservaIdSolicitada: reservaIdSolicitada,
    reservaEncontrada: reservaEncontrada ? {
      reserva_id: reservaEncontrada.reserva_id,
      habitacion_id: reservaEncontrada.habitacion_id,
      fecha_entrada: reservaEncontrada.fecha_entrada,
      fecha_salida: reservaEncontrada.fecha_salida,
      estado: reservaEncontrada.estado,
      pasajero: reservaEncontrada.pasajero || null
    } : null,
    montoPendiente: montoPendiente,
    nochesReserva: nochesReserva,

    esReclamoCobro: esReclamoCobro
  }
};

return [{ json: json }];

