const contexto = $('05 - Preparar Resultado').first().json;
const respuesta = $('06 - Generar Respuesta').first().json;
const judge = $('07 - Judge').first().json.output;

const texto = String(respuesta.text ?? '').trim();
const responseFinal = texto.length > 0
  ? texto
  : 'No pudimos procesar tu consulta de facturación en este momento. Por favor, contactá a recepción.';

return {
  json: {
    traceId: contexto.traceId,
    timestamp: new Date().toISOString(),

    channel: contexto.channel,
    sender: contexto.sender,
    message: contexto.message,
    intent: contexto.intent,

    approved: judge.approved,
    response: responseFinal,

    esReclamoCobro: contexto.result.esReclamoCobro || false,

    worker: {
      workflow: 'WF_WORKER_FACTURACION',
      stage: 'RESPUESTA_FINAL'
    },

    judge: judge
  }
};

const judge = $('07 - Judge').first().json.output;

let traceId = null;
try {
  traceId = $('05 - Preparar Resultado').first().json.traceId;
} catch (e) {
  try {
    traceId = $('02 - Validar Entrada').first().json.traceId;
  } catch (e2) {
    traceId = null;
  }
}

return {
  json: {
    status: 'BLOQUEADO',
    approved: false,
    response: null,

    traceId: traceId,
    timestamp: new Date().toISOString(),

    judge: judge,

    escalation: {
      required: true,
      reason: judge && judge.reason ? judge.reason : 'La respuesta de facturación no superó las validaciones de seguridad.'
    },

    worker: {
      workflow: 'WF_WORKER_FACTURACION',
      stage: 'ACTION_GATE'
    }
  }
};

const input = $json;

return {
  json: {
    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    channel: input.channel,
    recipient: input.sender,

    originalMessage: input.message,
    message: input.response,

    approved: input.approved,

    esReclamoCobro: input.esReclamoCobro || false,

    judge: input.judge ?? null,

    worker: {
      workflow: 'WF_WORKER_FACTURACION',
      stage: 'DISPATCH'
    },

    dispatch: {
      ready: true,
      source: 'WF_WORKER_FACTURACION'
    }
  }
};
